export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4.0;
  const g = inputs.gravity ?? 9.8;
  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * tTop));

  const tossedVelocity = u - g * t;
  const tossedAcceleration = -g;
  const tossedHeight = u * t - 0.5 * g * t * t;

  const isHeld = t < tTop;
  const dropVelocity = isHeld ? 0 : -g * (t - tTop);
  const dropAcceleration = isHeld ? 0 : -g;
  const dropHeight = isHeld ? yTop : tossedHeight;

  const laneWidth = 280;
  const laneHeight = 350;
  const laneY = 40;
  const tossX = 30;
  const dropX = 330;

  const stateTextToss = t === 0 ? "At launch" : t < tTop - 0.001 ? "Rising" : Math.abs(t - tTop) <= 0.001 ? "At the top" : t < 2 * tTop - 0.001 ? "Falling" : "At launch height";
  const stateTextDrop = isHeld ? "Held in place" : Math.abs(t - tTop) <= 0.001 ? "Just released" : t < 2 * tTop - 0.001 ? "Falling together" : "At launch height";

  const tossLane = sdk.panel({ x: tossX, y: laneY, w: laneWidth, h: laneHeight, title: "Toss lane", state: stateTextToss, id: "lane.toss" });
  const dropLane = sdk.panel({ x: dropX, y: laneY, w: laneWidth, h: laneHeight, title: "Drop lane", state: stateTextDrop, id: "lane.drop" });

  const yMin = 0;
  const yMax = 2.2;
  const axisX1 = tossX + 50;
  const axisX2 = dropX + 50;
  const axisY = laneY + laneHeight - 40;
  const axisLen = laneHeight - 90;

  const tossAxis = sdk.axis("axis.toss", { x: axisX1, y: axisY, length: axisLen, orientation: "y", min: yMin, max: yMax, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" });
  const dropAxis = sdk.axis("axis.drop", { x: axisX2, y: axisY, length: axisLen, orientation: "y", min: yMin, max: yMax, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" });

  const hToPx = (h) => axisY - (h / yMax) * axisLen;

  const ballX1 = tossX + 160;
  const ballY1 = hToPx(tossedHeight);
  const ballX2 = dropX + 160;
  const ballY2 = hToPx(dropHeight);
  const gateY = hToPx(yTop);

  const ballToss = sdk.circle("ball.toss", ballX1, ballY1, 28);
  const ballDrop = sdk.circle("ball.drop", ballX2, ballY2, 28);
  const releaseGate = sdk.gate("gate", ballX2, gateY, { open: !isHeld, label: " apex release" });

  const vecVToss = sdk.vector("vec.v.toss", { x: ballX1 - 22, y: ballY1 }, { value: tossedVelocity, direction: "up", scale: 12, label: "v" });
  const vecVDrop = sdk.vector("vec.v.drop", { x: ballX2 - 22, y: ballY2 }, { value: dropVelocity, direction: "up", scale: 12, label: "v" });

  const vecAToss = sdk.vector("vec.a.toss", { x: ballX1 + 22, y: ballY1 }, { value: tossedAcceleration, direction: "up", scale: 6, label: "a" });
  const vecADrop = sdk.vector("vec.a.drop", { x: ballX2 + 22, y: ballY2 }, { value: dropAcceleration, direction: "up", scale: 6, label: "a" });

  const calloutToss = sdk.callout(ballX1 + 35, ballY1 - 20, [`v = ${tossedVelocity.toFixed(2)} m/s`, `a = ${tossedAcceleration.toFixed(1)} m/s²`], { id: "callout.toss" });
  const calloutDrop = sdk.callout(ballX2 + 35, ballY2 - 20, [`v = ${dropVelocity.toFixed(2)} m/s`, `a = ${dropAcceleration.toFixed(1)} m/s²`], { id: "callout.drop" });

  const objects = [
    ...tossLane,
    ...dropLane,
    tossAxis,
    dropAxis,
    ballToss,
    ballDrop,
    ...releaseGate,
    ...vecVToss,
    ...vecVDrop,
    ...vecAToss,
    ...vecADrop,
    ...calloutToss,
    ...calloutDrop
  ];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tTop,
      apexHeight: yTop,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
